import 'package:fl_chart/fl_chart.dart';import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:uuid/uuid.dart';import '../../models/app_models.dart';import '../../providers/app_state.dart';
class HealthTrackerScreen extends ConsumerWidget{const HealthTrackerScreen({super.key});@override Widget build(BuildContext c,WidgetRef ref){final records=ref.watch(healthRecordsProvider);return Scaffold(appBar:AppBar(title:const Text('Health Tracker')),floatingActionButton:FloatingActionButton(onPressed:()=>ref.read(healthRecordsProvider.notifier).add(HealthRecord(id:const Uuid().v4(),userId:'demo',type:'Weight',value:70+records.length.toDouble(),unit:'kg')),child:const Icon(Icons.add)),body:ListView(padding:const EdgeInsets.all(16),children:[SizedBox(height:220,child:LineChart(LineChartData(lineBarsData:[LineChartBarData(spots:[for(var i=0;i<records.length;i++)FlSpot(i.toDouble(),records[i].value)],isCurved:true)]))),for(final r in records)Card(child:ListTile(leading:const Icon(Icons.monitor_heart),title:Text(r.type),subtitle:Text('${r.value} ${r.unit}')))]));}}
